#!/usr/bin/env bash
# Question 4: Restore etcd. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q4_NS}" create configmap before-backup --from-literal=state=kept --dry-run=client -o yaml | kubectl apply -f - >/dev/null
rm -rf "${Q4_DATADIR}"
command -v etcdutl >/dev/null || install -m 755 "/proc/$(pgrep -xo etcd)/root/usr/local/bin/etcdutl" /usr/local/bin/etcdutl
mkdir -p "$(dirname "${Q4_SNAPSHOT}")"
ETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 --cacert=/etc/kubernetes/pki/etcd/ca.crt --cert=/etc/kubernetes/pki/etcd/server.crt --key=/etc/kubernetes/pki/etcd/server.key snapshot save "${Q4_SNAPSHOT}" >/dev/null
kubectl -n "${Q4_NS}" create configmap after-backup --from-literal=state=lost --dry-run=client -o yaml | kubectl apply -f - >/dev/null
